mapper.select:
select content_id, content_type, title, sub_title, cover_image, cover_image_storage, cover_image_object_key, summary, content_html, sort_no, publish_status, publish_time, update_time
from hm_portal_content
where content_id = #{contentId}

mapper.insert:
insert into hm_portal_content(
    content_type, title, sub_title, cover_image, cover_image_storage, cover_image_object_key, summary, content_html, sort_no, publish_status, publish_time, update_time
) values (
    #{contentType}, #{title}, #{subTitle}, #{coverImage}, #{coverImageStorage}, #{coverImageObjectKey}, #{summary}, #{contentHtml}, #{sortNo}, #{publishStatus}, #{publishTime}, #{updateTime}
)

mapper.update:
update hm_portal_content
content_type = #{contentType}, title = #{title}, sub_title = #{subTitle}, cover_image = #{coverImage}, cover_image_storage = #{coverImageStorage}, cover_image_object_key = #{coverImageObjectKey}, summary = #{summary}, content_html = #{contentHtml}, sort_no = #{sortNo}, publish_status = #{publishStatus}, publish_time = #{publishTime}, update_time = #{updateTime}
where content_id = #{contentId}
